# meanings of the particles in each cell scene, shown in the on-stage key (see cc/flow-aid.js)
KN = {
 ('pancreatitis','necro'):{'inner':'digestive enzymes and ions held inside the cell','outer':'fluid and ions around the cell','leak':'enzymes escaping through the broken membrane to digest nearby tissue'},
 ('pancreatitis','hypoca'):{'inner':'calcium and other ions inside the cell','outer':'calcium outside the cell. Fewer dots mean less calcium'},
 ('aki','hyperk'):{'inner':'potassium inside the cell','outer':'potassium outside the cell. More dots outside make the resting membrane potential less negative'},
 ('aki','uremia'):{'inner':'ions and contents inside the cell','tox':'retained uraemic toxins that stick to the cell surface'},
 ('alf','hypoglyc'):{'inner':'glucose and ions inside the liver cell'},
 ('status','rhabdo'):{'inner':'potassium and contents inside the muscle fibre','outer':'potassium and contents that have escaped around the fibre','leak':'myoglobin and enzymes escaping through the ruptured membrane'},
}
